/*
* Safeguarding test for requirement: datazoom-handlelabel-show
* Verifies that `handleLabel.show` toggles normal-state handle label
* visibility, `emphasis.handleLabel.show` governs the emphasized state,
* and defaults preserve the previous behavior (hidden normally, shown on
* hover/drag).
*/

import { createChart, getECModel } from '../test/ut/core/utHelper';
import { EChartsType } from '../src/echarts';
import SliderZoomModel from '../src/component/dataZoom/SliderZoomModel';

function getSliderModel(chart: EChartsType): SliderZoomModel {
    return getECModel(chart).getComponent('dataZoom', 0) as SliderZoomModel;
}

describe('dataZoom handleLabel.show', function () {

    let chart: EChartsType;

    afterEach(function () {
        chart && chart.dispose();
    });

    function makeChart(dataZoom: object) {
        chart = createChart();
        chart.setOption({
            xAxis: { type: 'value' },
            yAxis: { type: 'value' },
            series: [{ type: 'line', data: [[11, 22], [33, 44]] }],
            dataZoom: [dataZoom]
        });
        return getSliderModel(chart);
    }

    it('defaults: normal label hidden, emphasis label shown (legacy behavior)', function () {
        const model = makeChart({ type: 'slider' });
        expect(model.get('handleLabel')).toBeFalsy();
        expect(model.getModel(['emphasis', 'handleLabel']).get('show')).toBe(true);
    });

    it('handleLabel.show toggles normal-state visibility', function () {
        const model = makeChart({ type: 'slider', handleLabel: { show: true } });
        const handleLabel = model.get('handleLabel') || {};
        expect(handleLabel.show).toBe(true);

        const model2 = (function () {
            chart.dispose();
            return makeChart({ type: 'slider', handleLabel: { show: false } });
        })();
        const handleLabel2 = model2.get('handleLabel') || {};
        expect(handleLabel2.show || false).toBe(false);
    });

    it('emphasis.handleLabel.show governs the emphasized state separately', function () {
        const model = makeChart({
            type: 'slider',
            handleLabel: { show: true },
            emphasis: { handleLabel: { show: false } }
        });
        expect((model.get('handleLabel') || {}).show).toBe(true);
        expect(model.getModel(['emphasis', 'handleLabel']).get('show')).toBe(false);
    });
});
